import{_ as e,o as i,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Orchestrator Meeting 2022-07-12","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2022-07-12","date":"2022-07-12T00:00:00.000Z","updated":"2022-07-20T00:00:00.000Z","tags":["Ceph","分布式存储","网络过滤","日志配置","二进制重构"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-07-12.md","filePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-07-12.md","lastUpdated":1780460162000}'),s={name:"posts/2022/Ceph_Orchestrator_Meeting_2022-07-12.md"};function o(p,t,n,a,_,g){return i(),l("div",null,[...t[0]||(t[0]=[r("<p>本次会议主要讨论了Ceph分布式存储系统中的网络过滤机制、日志配置以及二进制重构等方面的问题。</p><p><strong>关键细节</strong>：</p><ol><li><p><strong>fb filtering机制优化</strong>：</p><ul><li>讨论了当前fb filtering机制对网络匹配的严格要求，以及如何放宽匹配规则以允许更宽泛的子网匹配。</li><li>研究了使用Python标准库中的ipaddress库进行子网匹配检查的可行性。</li><li>决定尝试放宽匹配规则，并评估其对系统的影响。</li></ul></li><li><p><strong>日志配置优化</strong>：</p><ul><li>讨论了当前Ceph中二进制程序的日志级别固定为debug，导致日志文件中包含大量调试信息。</li><li>讨论了是否可以提供日志级别配置选项，允许用户根据需要调整日志输出。</li><li>讨论了使用环境变量、命令行参数和配置文件等方式进行日志级别配置的可行性。</li><li>决定优先考虑全局日志级别配置，并逐步优化。</li></ul></li><li><p><strong>日志内容优化</strong>：</p><ul><li>发现Ceph中存在大量冗余的日志信息，例如sc_status命令的输出。</li><li>讨论了是否可以将这些冗余信息移至silent级别，减少日志文件大小。</li><li>讨论了如何处理命令执行过程中的错误信息，确保调试信息对用户有价值。</li></ul></li><li><p><strong>二进制重构</strong>：</p><ul><li>讨论了Ceph二进制重构的进展，包括测试和构建过程。</li><li>决定继续进行测试，并评估是否需要运行额外的测试用例。</li></ul></li></ol><p><strong>后续行动计划</strong>：</p><ul><li>尝试放宽fb filtering机制的匹配规则，并评估其对系统的影响。</li><li>优先考虑全局日志级别配置，并逐步优化。</li><li>优化日志内容，减少冗余信息。</li><li>继续进行二进制重构测试，并评估是否需要运行额外的测试用例。</li></ul>",5)])])}const h=e(s,[["render",o]]);export{d as __pageData,h as default};
